package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with optional category filter
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	sortField := r.URL.Query().Get("sort")
	minPrice := r.URL.Query().Get("min_price")

	if category == "" {
		category = "all"
	}
	if sortField == "" {
		sortField = "name"
	}

	// Build query - parameterized for category and min_price
	var query string
	var args []interface{}

	if category == "all" {
		query = "SELECT id, name, price, description FROM products WHERE active = true"
	} else {
		query = "SELECT id, name, price, description FROM products WHERE active = true AND category = $1"
		args = append(args, category)
	}

	if minPrice != "" {
		if len(args) == 0 {
			query += " AND price >= $1"
		} else {
			query += fmt.Sprintf(" AND price >= $%d", len(args)+1)
		}
		args = append(args, minPrice)
	}

	// Sort field - validated against allowlist... but the check has a flaw
	allowedSorts := []string{"name", "price", "created_at", "rating"}
	sortValid := false
	for _, allowed := range allowedSorts {
		if strings.HasPrefix(sortField, allowed) {
			sortValid = true
			break
		}
	}

	if !sortValid {
		sortField = "name"
	}

	// ORDER BY is appended directly - can't use parameterized queries for identifiers
	query += " ORDER BY " + sortField

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("[\n"))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(",\n"))
		}
		first = false
		w.Write([]byte(fmt.Sprintf(`  {"id":%d,"name":"%s","price":%.2f,"description":"%s"}`, id, name, price, description)))
	}
	w.Write([]byte("\n]"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	log.Println("Starting product search service on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
